create table if not exists t_product (
	id bigint not null auto_increment,
	created_at timestamp not null default current_timestamp,
	updated_at timestamp not null default current_timestamp on update current_timestamp,
	deleted_at timestamp,
	code varchar(64) not null,
	barcode varchar(24),
	name varchar(256),
	description varchar(512),
	quantity integer default 0,
	unit_id bigint not null,
	unit_label varchar(32),
	category_code varchar(64),
	purchase_price decimal default 0,
	selling_price decimal default 0,
	rack_id bigint,
	rack_code varchar(64),
	rack_name varchar(256),
	expired_date date,
	primary key (id),
	index idx_t_product__code (code),
	index idx_t_product__barcode (barcode),
	index idx_t_product__category_code (category_code)
);


update t_product set barcode = code;
